import logging


logger = logging.getLogger("desktopenv.metrics.blender")


def _parse_blender_output(command_output):
    """Parse JSON output from blender check script."""
    try:
        if not command_output or not command_output.strip():
            logger.error("Empty command output")
            return None
        return json.loads(command_output.strip())
    except (json.JSONDecodeError, ValueError) as e:
        logger.error(f"Failed to parse blender output: {e}")
        logger.debug(f"Raw output: {command_output!r}")
        return None


def _find_object(result, name):
    """Find object by exact name in check_object.py output."""
    for obj in result.get("objects", []):
        if obj.get("name") == name:
            return obj
    return None


def _object_hidden_in_viewport(obj):
    """Return True when Blender reports the object hidden in the current viewport.

    `hide_viewport` is the object data-block viewport-disable flag, while
    `hide_get()` reflects interactive viewport hiding such as pressing H or
    using the Outliner eye icon. Older check scripts may only provide
    `hide_viewport`, so this keeps backward compatibility.
    """
    if obj.get("hide_viewport") is True:
        return True
    if obj.get("hide_get") is True:
        return True
    if obj.get("visible_get") is False:
        return True
    return False


def check_blender_object_visibility(command_output, rule):
    """Verify object viewport visibility state.

    Args:
        command_output: JSON from check_object.py
        rule: {"object_name": "Sphere", "hide_viewport": true}
              or {"object_name": "Sphere", "expected_visible": false}
    """
    try:
        result = _parse_blender_output(command_output)
        if result is None:
            return 0.0

        obj_name = rule.get("object_name", "")
        obj = _find_object(result, obj_name)
        if obj is None:
            return 0.0

        actual_hidden = _object_hidden_in_viewport(obj)
        if "hide_viewport" in rule:
            expected_hidden = bool(rule["hide_viewport"])
            if actual_hidden == expected_hidden:
                return 1.0
        elif "expected_visible" in rule:
            expected_visible = bool(rule["expected_visible"])
            if expected_visible == (not actual_hidden):
                return 1.0

        logger.warning(f"Visibility mismatch for '{obj_name}'")
        return 0.0
    except Exception as e:
        logger.error(f"check_blender_object_visibility error: {e}")
        return 0.0
